const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'S/ '+Number(n).toFixed(2);const groups=[{id:'Figuras',name:'Figuras para fiestas',image:10,price:'Desde S/65'},{id:'Cumpleaños',name:'Círculos en relieve',image:3,price:'Desde S/55'},{id:'Cuadros',name:'Cuadros personalizados',image:203,price:'Arte desde S/45'},{id:'Canilleras',name:'Canilleras',image:113,price:'Referencial S/65'}];let selected='Todos',limit=8,bag=[],delivery={},orderCode='';try{bag=JSON.parse(localStorage.getItem('encantada-v2-bag')||'[]');bag=bag.filter(i=>products.some(p=>p.id===i.id)&&Number.isInteger(i.qty)&&i.qty>0)}catch{bag=[]}function track(name){try{const stats=JSON.parse(localStorage.getItem('encantada-local-metrics')||'{}');stats[name]=(stats[name]||0)+1;localStorage.setItem('encantada-local-metrics',JSON.stringify(stats))}catch{}}function notify(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2500)}function save(){try{localStorage.setItem('encantada-v2-bag',JSON.stringify(bag))}catch{}$('#count').textContent=bag.reduce((n,i)=>n+i.qty,0)}function matches(p){return selected==='Todos'||(selected==='Cuadros'?(p.cat==='Cuadros'||p.cat==='Cuadros arte'):p.cat===selected)}function choose(cat){selected=cat;limit=8;render();$('#catalogTitle').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'})}$('#categories').innerHTML=groups.map(g=>`<button class="category" data-category="${g.id}"><img src="${products.find(p=>p.id===g.image).image}" alt=""><span><strong>${g.name}</strong><small>${g.price} ↗</small></span></button>`).join('');document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>choose(b.dataset.category));function render(){const q=$('#search').value.toLocaleLowerCase('es');const list=products.filter(p=>matches(p)&&`${p.name} ${p.theme}`.toLocaleLowerCase('es').includes(q));$('#catalogTitle').textContent=selected==='Todos'?'Encuentra tu diseño':groups.find(g=>g.id===selected)?.name||'Diseños especiales';$('#resultCount').textContent=list.length+' referencias disponibles';$('#filters').innerHTML=['Todos',...groups.map(g=>g.id),'Especiales'].map(c=>`<button class="${selected===c?'active':''}" data-chip="${c}">${c==='Todos'?'Ver todo':groups.find(g=>g.id===c)?.name||c}</button>`).join('');document.querySelectorAll('[data-chip]').forEach(b=>b.onclick=()=>choose(b.dataset.chip));$('#products').innerHTML=list.slice(0,limit).map(p=>{const price=p.cat==='Figuras'?65:p.variants?.[0]?.[1];return `<article class="product"><div class="product-photo" role="button" tabindex="0" data-product="${p.id}" aria-label="Personalizar ${p.name}"><img loading="lazy" src="${p.image}" alt="${p.name}"><span>${p.cat==='Cuadros'?'Precio por cotizar':p.cat}</span></div><h3>${p.name}</h3><div class="product-bottom"><strong>${price?'Desde '+money(price):'Cotiza tu idea'}</strong><button data-product="${p.id}">Personalizar ↗</button></div></article>`}).join('')||'<p>No encontramos esa temática. Escríbenos y consultamos tu idea.</p>';$('#showMore').hidden=list.length<=limit;document.querySelectorAll('[data-product]').forEach(b=>{b.onclick=()=>design(+b.dataset.product);b.onkeydown=e=>{if(e.key==='Enter'&&b.tagName!=='BUTTON')design(+b.dataset.product)}})}$('#search').oninput=()=>{limit=8;render()};$('#showMore').onclick=()=>{limit+=8;render()};function design(id){track('product_open');const p=products.find(p=>p.id===id),variants=p.cat==='Figuras'?[['1.50 m',65],['1.60 m',75],['1.70 m',85],['1.80 m',95]]:p.variants||[];$('#designerContent').innerHTML=`<div class="designer-grid"><div><div class="preview"><img src="${p.image}" alt="${p.name}"><div class="preview-label" id="previewLabel">Tu historia aquí<small>VISTA PREVIA ORIENTATIVA</small></div></div><p class="fine">La foto es una referencia real. El texto y color superpuestos comunican tu idea; no representan un diseño final aprobado.</p></div><div><span class="eyebrow">HAZLO TUYO · ENCANTADA</span><h2>${p.name}</h2><form id="designForm"><label>Texto o nombre para tu diseño<input name="personal" maxlength="60" required placeholder="Ej.: Valentina · 5 años"></label><label>Color de referencia</label><div class="swatches">${['#b51f62','#6b54a3','#22766c','#254e83','#bd8839'].map((c,i)=>`<button type="button" class="${i===0?'chosen':''}" style="--swatch:${c}" data-color="${c}" aria-label="Elegir color ${['rosado','morado','verde','azul','dorado'][i]}" aria-pressed="${i===0}"></button>`).join('')}</div><div class="row"><label>Medida<select name="size">${variants.length?variants.map(([v,n])=>`<option data-price="${n}" value="${v}">${v} · ${money(n)}</option>`).join(''):'<option data-price="0">Por coordinar</option>'}</select></label><label>Cantidad<input name="qty" type="number" value="1" min="1" max="100" required></label></div><label>Personaje y detalles adicionales<textarea name="notes" maxlength="500" placeholder="Temática, colores, referencia o consulta…"></textarea></label><p class="price-live" id="livePrice"></p><p class="fine">${p.cat==='Figuras'?'Precio por figura delgada; mayor ancho requiere cotización.':p.cat==='Canilleras'?'Confirma si el precio corresponde a unidad o par.':'Confirma materiales, acabado y contenido antes de producir.'} Entrega no incluida en el subtotal.</p><button class="button">Agregar a mi pedido +</button></form></div></div>`;let color='#b51f62';const form=$('#designForm'),update=()=>{$('#livePrice').textContent=+form.size.selectedOptions[0].dataset.price?money(+form.size.selectedOptions[0].dataset.price*(+form.qty.value||1))+' referencial':'Precio por cotizar'};form.personal.oninput=()=>{$('#previewLabel').firstChild.textContent=form.personal.value||'Tu historia aquí'};form.size.onchange=update;form.qty.oninput=update;document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{color=b.dataset.color;$('#previewLabel').style.setProperty('--accent',color);document.querySelectorAll('[data-color]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b))})});form.onsubmit=e=>{e.preventDefault();bag.push({id,qty:+form.qty.value,size:form.size.value,price:+form.size.selectedOptions[0].dataset.price,personal:form.personal.value,notes:form.notes.value,color});orderCode='';save();track('add_to_cart');$('#designer').close();notify('Agregado. Tu detalle ya está en el pedido ♡')};update();$('#designer').showModal()}
const galleryIds=[204,3,113,202,205,10];$('#gallery').innerHTML=galleryIds.map(id=>{const p=products.find(x=>x.id===id);return `<article><img loading="lazy" src="${p.image}" alt="Trabajo realizado: ${p.name}"><p>${p.name}</p></article>`}).join('');$('#prev').onclick=()=>$('#gallery').scrollBy({left:-270,behavior:'smooth'});$('#next').onclick=()=>$('#gallery').scrollBy({left:270,behavior:'smooth'});function totals(){const subtotal=bag.reduce((n,i)=>n+i.price*i.qty,0);return `<div class="cart-total">Subtotal referencial: <strong>${money(subtotal)}</strong>${bag.some(i=>!i.price)?' + productos por cotizar':''}<p class="fine">Entrega, diseños especiales y total final pendientes de confirmación.</p></div>`}function lines(){return bag.map((i,n)=>{const p=products.find(p=>p.id===i.id);return `<div class="cart-line"><img src="${p.image}" alt=""><div><strong>${p.name}</strong><p>${i.qty} × ${esc(i.size)} · ${i.price?money(i.price)+' c/u':'Por cotizar'}</p><p>${esc(i.personal)}</p></div><button data-remove="${n}" aria-label="Quitar ${p.name}">×</button></div>`}).join('')}function cartStep(step=1){$('#progressDelivery').classList.toggle('active',step>=2);$('#progressSummary').classList.toggle('active',step>=3);if(!bag.length){$('#cartContent').innerHTML='<h3>Tu pedido empieza con una idea.</h3><p>Explora los productos y personaliza tu favorito.</p><button class="button" id="backCatalog">Elegir un producto ↗</button>';$('#backCatalog').onclick=()=>{$('#cart').close();$('#coleccion').scrollIntoView()};return}if(step===1){$('#cartContent').innerHTML=lines()+totals()+'<div class="cart-actions"><button class="outline" id="continueShopping">Seguir eligiendo</button><button class="button" id="deliveryNext">Coordinar entrega →</button></div>';document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{bag.splice(+b.dataset.remove,1);orderCode='';save();cartStep()});$('#continueShopping').onclick=()=>$('#cart').close();$('#deliveryNext').onclick=()=>cartStep(2)}if(step===2){$('#cartContent').innerHTML=`<h3>¿Para quién y para cuándo?</h3><form id="deliveryForm"><label>Tu nombre<input name="customer" required maxlength="80" value="${esc(delivery.customer)}" autocomplete="given-name"></label><div class="row"><label>Fecha del evento<input name="date" type="date" required value="${esc(delivery.date)}"></label><label>Distrito / ciudad<input name="city" required maxlength="100" value="${esc(delivery.city)}" placeholder="Para consultar la entrega"></label></div><label>Modalidad<select name="mode"><option>Consultar delivery</option><option>Consultar recojo</option></select></label><p class="fine">La fecha y modalidad son una solicitud. El negocio debe confirmar disponibilidad, plazo y costo.</p><div class="cart-actions"><button type="button" class="outline" id="cartBack">← Productos</button><button class="button">Ver mi resumen →</button></div></form>`;$('#cartBack').onclick=()=>cartStep(1);$('#deliveryForm').onsubmit=e=>{e.preventDefault();delivery=Object.fromEntries(new FormData(e.target));cartStep(3)}}if(step===3){if(!orderCode)orderCode='ENC-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+Math.random().toString(36).slice(2,6).toUpperCase();$('#cartContent').innerHTML=`<span class="status">SOLICITUD · SIN CONFIRMAR</span><h3 style="margin-top:18px">Referencia ${orderCode}</h3><div class="summary-box"><p><b>${esc(delivery.customer)}</b> · ${esc(delivery.city)}</p><p>Evento: ${esc(delivery.date)} · ${esc(delivery.mode)}</p><p>${bag.map(i=>`${i.qty} × ${esc(products.find(p=>p.id===i.id).name)} (${esc(i.size)})`).join('<br>')}</p></div>${totals()}<p class="fine">Esta referencia se genera en tu navegador; no es una reserva ni un registro recibido por el negocio. Envía la solicitud por WhatsApp para confirmar diseño, entrega y total. Después podrás pagar por Yape.</p><div class="cart-actions"><button class="outline" id="deliveryBack">← Editar entrega</button><button class="button" id="sendOrder">Enviar solicitud por WhatsApp ↗</button></div><button class="footer-link" style="color:var(--pink);margin-top:25px" id="confirmedPay">Ya confirmé mi pedido: ver Yape</button>`;$('#deliveryBack').onclick=()=>cartStep(2);$('#sendOrder').onclick=()=>{track('whatsapp_order');const message=`Hola Encantada, quisiera confirmar esta solicitud: ${orderCode}\nNombre: ${delivery.customer}\nEvento: ${delivery.date}\nDistrito/ciudad: ${delivery.city}\nEntrega: ${delivery.mode}\n\n`+bag.map(i=>`${i.qty} × ${products.find(p=>p.id===i.id).name}\nMedida: ${i.size}\nTexto: ${i.personal}\nColor de referencia: ${i.color}\nDetalle: ${i.notes||'Sin detalle adicional'}\nPrecio referencial unitario: ${i.price?money(i.price):'por cotizar'}`).join('\n\n')+'\n\nPor favor confirmar material, contenido, diseño final, plazo, disponibilidad, entrega y total antes del pago.';window.open('https://wa.me/51934520463?text='+encodeURIComponent(message),'_blank','noopener')};$('#confirmedPay').onclick=()=>{$('#cart').close();$('#payment').showModal()}}}$('#cartOpen').onclick=()=>{track('cart_open');cartStep();$('#cart').showModal()};$('#payOpen').onclick=()=>$('#payment').showModal();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};$('#nav').querySelectorAll('a').forEach(a=>a.onclick=()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')});save();render();track('visit');

// Los enlaces internos desplazan la página actual: nunca abren /dist/.
document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const hash=a.getAttribute('href');const target=document.querySelector(hash);if(!target)return;e.preventDefault();target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});history.replaceState(null,'',hash)}));
if(location.hash==='#catalogo'){document.getElementById('coleccion').scrollIntoView();history.replaceState(null,'','#coleccion')}
if(matchMedia('(hover:hover)').matches&&!matchMedia('(prefers-reduced-motion:reduce)').matches){let scheduled=false;document.addEventListener('pointermove',e=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{document.documentElement.style.setProperty('--cursor-x',(e.clientX/innerWidth*100)+'%');document.documentElement.style.setProperty('--cursor-y',(e.clientY/innerHeight*100)+'%');scheduled=false})},{passive:true})}
